const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');

class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.refillRate = refillRate;
    this.buckets = new Map();
  }

  consume(clientId, tokens) {
    const now = Date.now();
    let bucket = this.buckets.get(clientId);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now };
      this.buckets.set(clientId, bucket);
    }

    const elapsed = (now - bucket.lastRefill) / 1000;
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsed * this.refillRate);
    bucket.lastRefill = now;

    // Check if enough tokens available
    if (bucket.tokens >= tokens) {
      bucket.tokens -= tokens;
      return true;
    }
    return false;
  }
}

class RequestValidator {
  constructor() {
    this.maxBodySize = 1048576; // 1MB
    this.allowedContentTypes = ['application/json'];
  }

  validateHeaders(req) {
    const contentType = req.headers['content-type'];
    if (contentType && !this.allowedContentTypes.some(t => contentType.startsWith(t))) {
      return { valid: false, error: 'Invalid content type' };
    }
    return { valid: true };
  }

  // Parse the X-Request-Cost header to determine rate limit cost
  getRequestCost(req) {
    const costHeader = req.headers['x-request-cost'];
    if (!costHeader) return 1;
    const parsed = parseInt(costHeader, 10);
    if (isNaN(parsed)) return 1;
    // Cap at maximum cost to prevent abuse
    if (parsed > 100) return 100;
    return parsed;
  }
}

class AuthService {
  constructor() {
    this.users = new Map();
    this.sessions = new Map();
    this.rateLimiter = new TokenBucket(20, 2);
    this.validator = new RequestValidator();
    this.loginAttempts = new Map();
    this.maxAttempts = 5;
    this.lockoutDuration = 900000; // 15 minutes
  }

  async register(username, password) {
    if (!username || !password) throw new Error('Missing credentials');
    if (typeof username !== 'string' || typeof password !== 'string') throw new Error('Invalid types');
    if (username.length < 3 || username.length > 64) throw new Error('Invalid username length');
    if (password.length < 8 || password.length > 128) throw new Error('Invalid password length');
    if (!/^[a-zA-Z0-9_]+$/.test(username)) throw new Error('Invalid username characters');
    if (this.users.has(username)) throw new Error('User exists');

    const hash = await argon2.hash(password, { type: argon2.argon2id });
    this.users.set(username, { hash, createdAt: Date.now() });
    return { success: true };
  }

  isLockedOut(username) {
    const attempts = this.loginAttempts.get(username);
    if (!attempts) return false;
    if (attempts.count >= this.maxAttempts) {
      if (Date.now() - attempts.lastAttempt < this.lockoutDuration) {
        return true;
      }
      this.loginAttempts.delete(username);
      return false;
    }
    return false;
  }

  recordFailedAttempt(username) {
    const attempts = this.loginAttempts.get(username) || { count: 0, lastAttempt: 0 };
    attempts.count += 1;
    attempts.lastAttempt = Date.now();
    this.loginAttempts.set(username, attempts);
  }

  async login(username, password) {
    if (!username || !password) throw new Error('Missing credentials');
    if (typeof username !== 'string' || typeof password !== 'string') throw new Error('Invalid types');

    if (this.isLockedOut(username)) {
      throw new Error('Account locked');
    }

    const user = this.users.get(username);
    if (!user) {
      this.recordFailedAttempt(username);
      throw new Error('Invalid credentials');
    }

    const valid = await argon2.verify(user.hash, password);
    if (!valid) {
      this.recordFailedAttempt(username);
      throw new Error('Invalid credentials');
    }

    this.loginAttempts.delete(username);
    const token = crypto.randomBytes(32).toString('hex');
    this.sessions.set(token, { username, createdAt: Date.now(), expiresAt: Date.now() + 3600000 });
    return { token };
  }

  validateSession(token) {
    if (!token || typeof token !== 'string') return null;
    const session = this.sessions.get(token);
    if (!session) return null;
    if (Date.now() > session.expiresAt) {
      this.sessions.delete(token);
      return null;
    }
    return session;
  }
}

const app = express();
const auth = new AuthService();

app.use(express.json({ limit: '1mb' }));

// Rate limiting middleware
app.use((req, res, next) => {
  const clientId = req.ip;
  const cost = auth.validator.getRequestCost(req);

  if (!auth.rateLimiter.consume(clientId, cost)) {
    return res.status(429).json({ error: 'Rate limited' });
  }
  next();
});

app.post('/register', async (req, res) => {
  try {
    const result = await auth.register(req.body.username, req.body.password);
    res.json(result);
  } catch (e) {
    res.status(400).json({ error: e.message });
  }
});

app.post('/login', async (req, res) => {
  try {
    const result = await auth.login(req.body.username, req.body.password);
    res.json(result);
  } catch (e) {
    res.status(401).json({ error: e.message });
  }
});

app.get('/protected', (req, res) => {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  const session = auth.validateSession(token);
  if (!session) return res.status(401).json({ error: 'Unauthorized' });
  res.json({ message: 'Protected data', user: session.username });
});

module.exports = app;
